// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint64 warpTo, uint256 unlockTime, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        warpTo = uint64(bound(uint256(warpTo), 1, 2e18));
        amount = bound(amount, 0, 100 ether);
        vm.warp(warpTo);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 accUnlockTime, ) = c.Acc(actor);
        assertTrue(accUnlockTime >= block.timestamp);
    }
}
